#!/usr/bin/env python3
"""Source-led UK decision routes; no popularity or hands-on testing claims."""
from pathlib import Path
import json,re
from html import escape
ROOT=Path(__file__).resolve().parents[1]; SITE=ROOT/'site'
BASE='https://getecoback.com'
HUB='en/guide/uk-damp-and-heating-decisions.html'
COMPARE='en/guide/12l-vs-20l-dehumidifier-uk.html'
def meaco_care():
 return '''<section id="meaco-care" aria-labelledby="meaco-care-heading"><p class="winter-kicker">Keep the appliance you have · UK filter care</p><h2 id="meaco-care-heading">Does this Meaco filter fit, and do you need it?</h2><p>Choose from the labels on your appliance. No account, measurements or typing needed. This check covers the official Arete One/Two 10L/12L H13 filter listing only; other sizes remain unverified.</p><form hidden><label>Model generation<select name="generation"><option value="unknown">Not checked yet</option><option value="one">Arete One</option><option value="two">Arete Two</option><option value="other">Another family / not sure</option></select></label><label>Capacity on the label<select name="size"><option value="unknown">Not checked yet</option><option value="10">10L</option><option value="12">12L</option><option value="20">20L</option><option value="25">25L</option><option value="other">Another size / not sure</option></select></label><label>Your purpose<select name="purpose"><option value="unknown">Help me decide</option><option value="dry">Dehumidifying only</option><option value="air">Additional air filtration</option></select></label><button type="submit">Show care guidance</button></form><noscript><p>The model and maintenance guidance below works without JavaScript. Interactive selection and copying require JavaScript.</p></noscript><div data-care-result hidden tabindex="-1" aria-live="polite"><h3 data-care-title></h3><p data-care-text></p><p data-care-cost-link hidden><a href="#meaco-care-cost">See the dated cost example and its limits</a>.</p><button type="button" data-care-copy disabled>Copy this guidance</button><p data-care-status role="status"></p><label data-care-copy-box hidden>Guidance to copy<textarea data-care-fallback readonly aria-label="Guidance to copy"></textarea></label></div><h3>Model match and a no-purchase option</h3><p>The <a href="https://www.meaco.com/products/meacodryarete10l-12lhepafilter">official Meaco 10L/12L H13 filter page</a>, read on <time datetime="2026-10-17">17 October 2026</time>, lists Arete One 10L, Arete One 12L, Arete Two 10L and Arete Two 12L. This is not verification for 20L, 25L, Platinum or a similar-looking filter.</p><p>For this verified family, Meaco says the additional HEPA filter does not have to be fitted all the time. For dehumidifying alone it is optional. Keep and maintain the standard dust filter as directed in your model manual. The manufacturer says adding HEPA slightly reduces water extraction efficiency and increases noise. This page does not assess medical needs or promise health benefits.</p><p>Do not wash, cut or improvise a HEPA filter. The standard dust filter and the replaceable HEPA filter are different parts; follow the exact model manual for cleaning and replacement.</p><h3 id="meaco-care-cost">Annual consumption is not the same as buying whole packs</h3><p>The official listing showed <strong>£29.99 for three filters</strong> when read on 17 October 2026. It showed unavailable stock at that reading; that is a dated observation, not a current stock promise. Check the exact item, current stock, delivery charges and return conditions with the seller before buying. This is an ordinary manufacturer source, not an affiliate buying link.</p><p>The manufacturer gives roughly three months as a replacement reference, depending on conditions. It is not a guaranteed filter lifespan. The example below uses four filters in a year and starts with no filters in hand; any filter included with your appliance is excluded.</p><div class="care-table"><table><caption>Illustration at the dated pack price; not a quote or a replacement schedule</caption><thead><tr><th scope="col">What is counted</th><th scope="col">Example</th></tr></thead><tbody><tr><th scope="row">Annual filters consumed</th><td>4 filters</td></tr><tr><th scope="row">Annual consumption cost</th><td>4 × (£29.99 ÷ 3) = £39.99, rounded</td></tr><tr><th scope="row">Whole packs bought from zero stock</th><td>2 packs × £29.99 = £59.98</td></tr><tr><th scope="row">Filters left after that year</th><td>6 bought − 4 used = 2</td></tr></tbody></table></div><p class="care-note">Unused filters are inventory, not money lost or a cash saving. Delivery, future prices, disposal, electricity and any included filter are excluded. Follow your manual and filter condition instead of treating this example as a personal replacement schedule.</p></section>'''
def link(path,text):return f'<a href="/{path}">{text}</a>'
def localize_laundry_copy(html):
 """Keep this UK route's static examples aligned with its fictional GBP default.

 Run after generic chrome/buyer injection; other markets remain unchanged.
 These are new illustrative GBP amounts, not converted prices or live tariffs.
 """
 replacements={
  'placeholder="Ratgeber durchsuchen …"':'placeholder="Search guides …"',
  'aria-label="Suche"':'aria-label="Search guides"',
  '€0.30/kWh':'GBP 0.35/kWh (35p/kWh)',
  'The €0.30 used above':'The fictional GBP 0.35/kWh used above',
  '<td>6.0 ct</td><td>€0.36</td><td>€4.32</td>':'<td>7.0p</td><td>GBP 0.42</td><td>GBP 5.04</td>',
  '<td>9.0 ct</td><td>€0.54</td><td>€6.48</td>':'<td>10.5p</td><td>GBP 0.63</td><td>GBP 7.56</td>',
  '<td>15.0 ct</td><td>€0.90</td><td>€10.80</td>':'<td>17.5p</td><td>GBP 1.05</td><td>GBP 12.60</td>',
  'EUR 0.70 at EUR 0.35/kWh':'GBP 0.70 at GBP 0.35/kWh',
  '€0.35/kWh = €0.45':'GBP 0.35/kWh = GBP 0.45 (rounded)',
 }
 for old,new in replacements.items():html=html.replace(old,new)
 return html
def main():
 cap=json.loads((ROOT/'data/ofgem-cap.json').read_text());rate=cap['electricity_p_per_kwh']
 routes=[('dehumidifier-drying-clothes-cost','Compare the cost of drying the same laundry load'),('heated-airer-vs-dehumidifier','Heated airer or dehumidifier: where does the moisture go?'),('desiccant-vs-compressor-dehumidifier','Cold room: desiccant or compressor?'),('rising-damp-penetrating-damp-or-condensation','Damp patches: investigate the cause before buying'),('keep-warm-working-from-home','Personal warmth versus heating a room'),('draughty-windows-rented-home','Draughty rental windows: reversible checks')]
 cards='<nav class="winter-grid" aria-label="UK decisions">'+''.join(link('en/guide/'+s+'.html',t) for s,t in routes)+'</nav>'
 hub=f"""<h2>Choose the problem you need to solve</h2><p>For a UK home with slow-drying washing, cold rooms or damp patches, start with the job, not a product ranking. These routes combine UK sources with our existing calculators. We have not tested the appliances ourselves.</p>{cards}<h2>Buying a dehumidifier: what does 12L or 20L actually mean?</h2><p>A headline litres-per-day rating is tied to test conditions. Compare extraction and watts at the same temperature and relative humidity before using room-count marketing.</p><p>{link(COMPARE,'Read the 12L versus 20L condition-matched comparison')}.</p><h2>Drying washing: compare a completed load</h2><p>A heated airer evaporates water into the room; it does not collect it. Ventilation and dehumidification can remove moisture, but they have different operating costs and depend on conditions. Compare the same laundry mass and final dryness, including any airer and dehumidifier used together.</p><p>{link('en/guide/dehumidifier-drying-clothes-cost.html#laundry-check','Open the existing laundry cost calculator')}. The calculator starts with a fictional GBP example. Replace its rate with your bill: {rate}p is £{rate/100:.4f}/kWh. Use measured session kWh where possible rather than assuming nameplate power throughout.</p><h2>A dated electricity reference, not a UK-wide tariff</h2><p>Ofgem lists <strong>{rate}p/kWh</strong> as the average Direct Debit electricity unit rate for <strong>{escape(cap['period'])}</strong> in England, Scotland and Wales. Actual rates vary by region, payment method and plan. This is not a Northern Ireland tariff; enter the rate on your own bill. Standing charges are excluded from appliance running costs. The headline annual price-cap figure is not a maximum household bill.</p><p>Read from <a href="{cap['source']}">Ofgem’s unit-rate table</a> on {cap['fetched']}. Recheck the applicable period before using this reference.</p><h2>Oil-filled radiator, fan heater or heated throw?</h2><p>For a plug-in resistance heater, oil is a way to store and release heat, not a free energy source. Two devices averaging the same electrical input over the same time use the same kWh. Their controls, heat distribution and cycling can differ. A heated throw warms a person rather than the whole room: a lower cost does not establish equivalent service or suitable room conditions.</p><p>Illustrative continuous operation for four hours at the reference rate: a 100 W device uses 0.4 kWh (£{.4*rate/100:.2f}); a 2,000 W device uses 8 kWh (£{8*rate/100:.2f}). These are invented power examples, not measured products or promised savings. Formula: watts ÷ 1,000 × hours × pence/kWh ÷ 100.</p><p>{link('en/guide/keep-warm-working-from-home.html','Work-from-home warmth and room-condition checks')}. See <a href="https://www.moneysavingexpert.com/utilities/heat-the-human-not-the-home-save-energy/">MoneySavingExpert’s personal-warmth guidance</a> and follow the appliance’s safety instructions. Keep necessary ventilation open; <a href="https://energysavingtrust.org.uk/advice/draught-proofing/">Energy Saving Trust explains the distinction between draughts and ventilation</a>.</p><h2>Damp in a rented home: keep a useful record</h2><p>A dehumidifier cannot repair a leak or a building defect. Record the date, room, location of patches, whether rain or plumbing use precedes them, any available temperature and humidity readings, photographs, and when the problem was reported. Readings alone do not diagnose the cause. Keep the record privately; this page does not collect it.</p><ul><li>Date and room; patch location and changes since the last observation.</li><li>Rain, visible leaks and ventilation or heating faults observed, without guessing a diagnosis.</li><li>Photograph filenames; optional measured temperature and humidity with time.</li><li>Report date, repair reference and follow-up response.</li></ul><p><a href="https://england.shelter.org.uk/housing_advice/repairs/damp_and_mould_in_rented_homes">Shelter England’s damp and mould guidance</a> explains why underlying causes need investigation. That legal guidance is for England; use the appropriate local service in Scotland, Wales or Northern Ireland. Do not wait for a monitoring exercise before reporting a serious leak or health concern.</p><h2>Before spending money</h2><p>First establish whether this is a repair, ventilation, laundry or heating problem. Then check temperature-specific performance, noise at the intended setting, tank emptying or drainage, purchase cost and return conditions. No particular saving is guaranteed.</p>"""
 comparison="""<h2>Compare the same temperature and humidity</h2><p>The figures below are manufacturer specifications for the MeacoDry Arete One family, read on 4 October 2026. They are not EcoBack measurements, an independent ranking, or a comparison with Arete Two. Litres/day describe water extraction at the stated test point.</p><div style="overflow-x:auto"><table><thead><tr><th>Model</th><th>Conditions</th><th>Extraction</th><th>Power</th></tr></thead><tbody><tr><td>Arete One 12L</td><td>10°C / 60% RH</td><td>1.95 L/day</td><td>130 W</td></tr><tr><td>Arete One 20L</td><td>10°C / 60% RH</td><td>3.4 L/day</td><td>180 W</td></tr><tr><td>Arete One 12L</td><td>20°C / 60% RH</td><td>5.23 L/day</td><td>151 W</td></tr><tr><td>Arete One 20L</td><td>20°C / 60% RH</td><td>8.5 L/day</td><td>216 W</td></tr></tbody></table></div><p>The same 12L model lists 12.18 L/day at 30°C / 80% RH. That does not mean it will remove 12 litres per day in a cool UK bedroom. Both models extract less at the cooler 10°C / 60% test point than at 20°C / 60%.</p><h2>Does the lower-wattage machine cost less to finish the job?</h2><p>Not necessarily. At the 20°C / 60% test point, the 12L model has lower power but also lower water extraction. Hourly cost is not the same as cost to reach a target humidity or dry a load. Real conditions change during operation, and cycling, ventilation and new moisture affect the result. Measure a whole comparable session before claiming a saving.</p><h2>When a larger capacity may be useful</h2><p>Consider a larger model if the smaller one cannot maintain the chosen conditions despite correct use and resolving moisture sources, or if its tank and operating schedule do not suit you. This table alone cannot establish the capacity required for a specific home. A larger tank may reduce emptying, but tank size is not extraction capacity.</p><h2>Why bedroom count is an incomplete shortcut</h2><p>Note the actual room volume, temperature, moisture source, door arrangement and airflow. A unit in a hallway is not guaranteed to control closed bedrooms. Noise at your chosen setting, drainage, placement clearances and the ability to move the unit also matter. Ask for performance at relevant temperature and humidity, rather than relying solely on the advertised number of rooms.</p><h2>A cold room changes the decision</h2><p>Check the manufacturer’s operating range and performance curve. A cold-room decision may involve compressor versus desiccant operation, but do not assume that a technology label proves the lower whole-session cost. Follow the actual manual and account for the room’s moisture source.</p><p><a href="/en/guide/desiccant-vs-compressor-dehumidifier.html">Compare desiccant and compressor operation</a> · <a href="/en/guide/dehumidifier-drying-clothes-cost.html#laundry-check">Measure laundry running cost</a>.</p><h2 id="purchase-checklist">UK purchase checklist</h2><p>Check the exact model and seller before paying. A German listing or an English-language page does not establish UK compatibility or delivery. EcoBack has not verified a UK affiliate buying link for these models; the manufacturer links below are ordinary sources, not commission links.</p><ul><li>Confirm the exact model generation and condition-matched extraction and watts.</li><li>Check noise at the intended setting, tank access, drainage and placement.</li><li>Identify leaks or ventilation faults that a purchase would not fix.</li><li>Use your own tariff and a full session, not only maximum nameplate watts.</li><li>Confirm the model generation, UK plug and rated voltage in the manufacturer specification and the exact seller listing; do not assume an imported variant is equivalent.</li><li>Check delivery to your postcode, including any Northern Ireland or island exclusions, total delivered price in GBP, warranty coverage and who handles returns.</li><li>Check current availability and return terms directly; this page makes no stock or price promise.</li></ul><h2>Manufacturer sources</h2><p><a href="https://www.meaco.com/products/meacodryarete1-12l">MeacoDry Arete One 12L specifications</a> · <a href="https://www.meaco.com/products/meacodry-arete-one-20l-dehumidifier-and-air-purifier">MeacoDry Arete One 20L specifications</a>. These source links are not an independent endorsement or a claim that either is the best purchase for your home.</p>"""
 hub += '<h2>Already own a Meaco? Check the filter before buying</h2><p>Match the exact model, distinguish the standard dust filter from optional HEPA, and compare annual filter consumption with whole-pack spending. '+link(COMPARE+'#meaco-care','Open the UK filter care check')+'. No verified UK affiliate buying link is added.</p>'
 comparison = comparison.replace('<h2 id="purchase-checklist">',meaco_care()+'<h2 id="purchase-checklist">')
 for path,title,desc,body in [(HUB,'UK damp, laundry and heating: choose your next step','UK home energy decisions: laundry costs in GBP, condition-matched dehumidifier sizing, personal warmth and rented-home damp records.',hub),(COMPARE,'12L or 20L dehumidifier for a UK home?','Compare manufacturer extraction and watts at matching temperature and humidity. Understand why headline capacity and bedroom counts do not settle the decision.',comparison)]:
  url=BASE+'/'+path;schema={'@context':'https://schema.org','@type':'Article','headline':title,'description':desc,'datePublished':'2026-10-04','dateModified':'2026-10-17','inLanguage':'en-GB','url':url,'author':{'@type':'Organization','name':'EcoBack'}}
  care_assets='<link rel="stylesheet" href="/assets/meaco-care.css"><script type="module" src="/assets/meaco-care.mjs"></script>' if path==COMPARE else ''
  html=f'<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title} | EcoBack</title><meta name="description" content="{desc}"><link rel="canonical" href="{url}">\n<link rel="stylesheet" href="/assets/winter.css">{care_assets}<script type="application/ld+json">{json.dumps(schema)}</script></head><body class="winter-page"><main class="winter-wrap"><nav><a href="/en/">English home</a> · {link(HUB,"UK decisions")} · <a href="/en/winter-energy-saving.html">Winter tools</a></nav><header class="winter-hero"><p class="winter-kicker">EcoBack · United Kingdom</p><h1>{title}</h1><p class="winter-lead">{desc}</p><p>Source-based guidance · Updated 17 October 2026 · No hands-on product tests</p></header><article>{body}<p>{link(HUB,"All UK decisions")} · <a href="/en/how-we-recommend.html">Editorial method</a> · <a href="/datenschutz.html">Privacy (German)</a></p></article></main></body></html>'
  (SITE/path).write_text(html)
 for path in ['index.html','en/index.html']+['en/guide/'+s+'.html' for s,_ in routes]+['en/guide/desiccant-vs-compressor-dehumidifier.html']:
  file=SITE/path;s=file.read_text();s=re.sub(r'<!--EB_UK_PATH-->.*?<!--/EB_UK_PATH-->','',s,flags=re.S)
  if path=='en/guide/dehumidifier-drying-clothes-cost.html':
   s=localize_laundry_copy(s)
   # These generic promotions select a German store independently of the
   # buyer module's explicit market choice. No verified UK affiliate route yet.
   for marker in ['EB_STICKY','EB_PROFILE']:
    s=re.sub(r'<!--'+marker+r'-->.*?<!--/'+marker+r'-->','',s,flags=re.S)
  label='Großbritannien: Feuchtigkeit, Wäsche und Heizkosten (Englisch)' if path=='index.html' else 'UK: damp, laundry and heating decisions'
  block=f'<!--EB_UK_PATH--><aside style="max-width:1000px;margin:24px auto;padding:20px;background:#edf3e6;color:#203a32"><p style="font-size:1.2rem;font-weight:700">{link(HUB,label)}</p><p>{link(COMPARE,"12L vs 20L: compare the same temperature and humidity")}</p></aside><!--/EB_UK_PATH-->'
  marker=re.search(r'</header>',s) or re.search(r'<main[^>]*>',s) or re.search(r'<body[^>]*>',s)
  file.write_text(s[:marker.end()]+block+s[marker.end():])
 print('Built 2 UK decision pages and linked existing tools and homepages.')
if __name__=='__main__':main()

